\label{Lemma10} Under \cref{Assumption1} and \cref{Assumption2}, suppose the total iteration rounds of \cref{alg1} is $T$. If at least one of $k_2$ and $k_3$ in \cref{Lemma6} exists, we denote $k_{\text{min}} := \min\{k_2, k_3\}$. Then we have the upper bound of $\bar{z}_t$ as:
\begin{align}
\bar{z}_t \leq
\begin{cases}
C_z, & t \leq k_{\text{min}}, \\
a_1 \log(t) + b_1, & t > k_{\text{min}},
\end{cases}\label{eq83}
\end{align}
where $a_1, b_1$ are defined as:
\begin{align}
a_1:= 6a_0,\quad b_1:= 4a_0 \log \left( 1 + \frac{nC_{l_{xy}} \bar{b} + nC_{f_x} + \bar{m}^x_0}{nC_{l_{xy}} \bar{a}} \right) + 4a_0\log \left( nC_{l_{xy}} \bar{a}\right) + 4a_0 + 2b_0,\label{eq84}
\end{align}
in which we define constants
\begin{align}
\bar{a} &:= \frac{\sqrt{2n}}{\mu}, \quad
\bar{b} := \frac{\sqrt{2n}C_{f_y}}{\mu}, \notag\\
a_0 &:= \left( \frac{1}{\mu^2}\left(8+\frac{4(\mu + C_{l_{yy}})^2}{\mu C_{l_{yy}}} \right)\left(\frac{nL_{l,2}C_{f_y}}{\mu}+L_{f,1}\right)^2+1\right) \notag \\
&\quad \cdot\left(\frac{32 \gamma_x^2 \rho_W(1 + \zeta_q^2)}{n(1 - \rho_W)^2} \left(\frac{(\mu+L_{l,1})^3}{\gamma_y\mu^2}+\frac{2L_{l,1}(\mu+L_{l,1})}{\gamma_y\mu}\right)+\frac{8\gamma_x^2  L_y^2\left( 1 + \zeta_q^2 \right) (\mu + L_{l,1})^2}{n\gamma_y^2\mu L_{l,1}\sqrt{1+\sigma_u^2}}\right)\nonumber\\
&\quad +\frac{16(\mu + C_{l_{yy}})}{n\gamma_v\mu^2\sqrt{1+\sigma_u^2}}\left(\frac{nL_{l,2}C_{f_y}}{\mu}\!+\!L_{f,1}\right)^2\left(\frac{4 \gamma_x^2 \rho_W (1 + \zeta_q^2)}{\bar{z}_0^2(1 - \rho_W)^2} \right.\nonumber\\
&\quad \left.\cdot\left(\frac{(\mu+L_{l,1})^2\sqrt{1+\sigma_u^2}}{n\mu^2 }+\frac{2L_{l,1}\sqrt{1+\sigma_u^2}}{n\mu }\right)+\frac{\gamma_x^2L_y^2(1+\zeta_q^2)(\mu + L_{l,1})}{n\bar{z}_0\gamma_y \mu L_{l,1}}\right)\nonumber\\
&\quad+ \frac{64 \gamma_x^2 \rho_W \bar{L}_r^2(\mu + C_{l_{yy}})(1 + \zeta_q^2)}{n\mu C_{l_{yy}}\gamma_v(1 - \rho_W)^2} + \frac{2\gamma_x^2L_v^2(1+\zeta_q^2)(\mu + C_{l_{yy}})^2}{n\mu C_{l_{yy}}\bar{m}_0^v\gamma_v^2\sqrt{1+\sigma_z^2}}, \notag\\
b_0 &:=C_{m^y} + C_{m^v} +\frac{4C_{m^y}^2(\mu + C_{l_{yy}})}{\mu^4\gamma_v\sqrt{1+\sigma_z^2}}\left(\frac{nL_{l,2}C_{f_y}}{\mu}+L_{f,1}\right)^2 \nonumber\\
&\quad+ \frac{8(\mu + C_{l_{yy}})C_{m^v}^2}{\mu^2\gamma_v\sqrt{1+\sigma_z^2}} + \frac{16(\mu + C_{l_{yy}})}{n\gamma_v\mu^2}\left(\frac{nL_{l,2}C_{f_y}}{\mu}\!+\!L_{f,1}\right)^2 \notag \\
&\quad \cdot \left(\frac{\Delta_0^x}{1-\rho_W}\!+\!\frac{4 \gamma_x^2 \rho_WC_{m^x}^2 (1 + \zeta_q^2)}{\bar{q}_0^2(1 - \rho_W)^2} \right)\left(\frac{(\mu+L_{l,1})^2}{n\mu^2 }\!+\!\frac{2L_{l,1}}{n\mu }\right)\notag \\
&\quad+\left(\frac{16\Delta_0^x}{n(1-\rho_W)}+\frac{64\gamma_x^2\rho_WC_{m^x}^2(1+\zeta_q^2)}{n\bar{q}_0^2(1-\rho_W)^2}\right)\left(\frac{ \bar{L}_r^2(\mu + C_{l_{yy}})}{\mu C_{l_{yy}}\gamma_v}+\frac{\bar{L}_r^2(\mu+C_{l_{yy}})}{\mu^2\gamma_v\sqrt{1+\sigma_z^2}}\right) \notag \\
&\quad  +\left[ \frac{1}{\mu^2}\left(8+\frac{4(\mu + C_{l_{yy}})^2}{\mu C_{l_{yy}}} \right)\left(\frac{nL_{l,2}C_{f_y}}{\mu}+L_{f,1}\right)^2+1\right]\left(\frac{C_{m^y}^2}{\bar{m}^y_0} - {\bar{m}^y_0}\right)  \notag \\
&\quad  +\left[ \frac{1}{\mu^2}\left(8+\frac{4(\mu + C_{l_{yy}})^2}{\mu C_{l_{yy}}} \right)\left(\frac{nL_{l,2}C_{f_y}}{\mu}+L_{f,1}\right)^2+1\right]\left(\frac{ 2C_{m^y}^2(\mu + L_{l,1})}{\mu^2\gamma_y\sqrt{1+\sigma_u^2}} \right.\notag\\
&\quad+\left(\frac{8\Delta_0^x}{n(1-\rho_W)}+\frac{32 \gamma_x^2 \rho_WC_{m^x}^2 (1 + \zeta_q^2)}{n\bar{q}_0^2(1 - \rho_W)^2} \right)\left(\frac{(\mu+L_{l,1})^3}{\gamma_y\mu^2}+\frac{2L_{l,1}(\mu+L_{l,1})}{\gamma_y\mu}\right)\nonumber\\
&\quad\left.+ \frac{32 \gamma_x^2 \rho_W(1 + \zeta_q^2)}{n\bar{z}_0(1 - \rho_W)^2} \left(\frac{(\mu+L_{l,1})^3}{\gamma_y\mu^2}+\frac{2L_{l,1}(\mu+L_{l,1})}{\gamma_y\mu}\right)+\frac{8\gamma_x^2  L_y^2\left( 1 + \zeta_q^2 \right) (\mu + L_{l,1})^2}{n\gamma_y^2\mu L_{l,1}\bar{z}_0\sqrt{1+\sigma_u^2}} \right). \label{eq85}
\end{align}

When neither $k_2$ nor $k_3$ exists, we have $\bar{z}_t \leq C_z$ for all $t \leq T$.

\begin{align}
\bar{z}_t \leq
\begin{cases}
C_z, & t \leq k_{\text{min}}, \\
a_1 \log(t) + b_1, & t > k_{\text{min}},
\end{cases}\label{eq83}
\end{align}

\begin{align}
a_1:= 6a_0,\quad b_1:= 4a_0 \log \left( 1 + \frac{nC_{l_{xy}} \bar{b} + nC_{f_x} + \bar{m}^x_0}{nC_{l_{xy}} \bar{a}} \right) + 4a_0\log \left( nC_{l_{xy}} \bar{a}\right) + 4a_0 + 2b_0,\label{eq84}
\end{align}

To begin with, we first show the following result as the first two lines of \cref{eq82}: since $\bar{m}^y_t$ and $\bar{m}^v_t$ are positive and increasing monotonically with $t$, we can easily have:
\begin{align}
0& \leq \min\{[\bar{m}^y_{t+1}]^2, [\bar{m}^v_{t+1}]^2\} - \min\{[\bar{m}^y_{t}]^2, [\bar{m}^v_{t}]^2\} \nonumber\\
&= \left([\bar{m}^y_{t+1}]^2 + [\bar{m}^v_{t+1}]^2 - \max\{[\bar{m}^y_{t+1}]^2, [\bar{m}^v_{t+1}]^2\}\right) - \left([\bar{m}^y_{t}]^2 +[\bar{m}^v_{t}]^2 - \max\{[\bar{m}^y_{t}]^2, [\bar{m}^v_{t}]^2\}\right) \nonumber\\
&\overset{(a)}{=} ([\bar{m}^y_{t+1}]^2 + [\bar{m}^v_{t+1}]^2) - ([\bar{m}^y_{t}]^2 +[\bar{m}^v_{t}]^2) - (\bar{z}_{t+1}^2 - \bar{z}_t^2),\label{eq86}
\end{align}
where (a) uses the definition $\bar{z}_t := \max\{\bar{m}^v_t, \bar{m}^y_t\}$. Similar to \cref{eq82}, we have:
\begin{align}
\bar{z}_{t+1}^2 - \bar{z}_t^2
\leq ([\bar{m}^y_{t+1}]^2-[\bar{m}^y_{t}]^2) + ([\bar{m}^v_{t+1}]^2-[\bar{m}^v_{t}]^2)= \frac{\|\nabla_y L(\mathbf{x}_t, \mathbf{y}_t)\|^2}{n} + \frac{\|\nabla_v R(\mathbf{x}_t, \mathbf{y}_t, \mathbf{v}_t)\|^2}{n},\label{eq87}
\end{align}
which indicates that
\begin{align}
\bar{z}_{t+1} 
&\leq \bar{z}_{t} + \frac{\|\nabla_y L(\mathbf{x}_t, \mathbf{y}_t)\|^2}{n(\bar{z}_{t+1}+\bar{z}_{t})} + \frac{\|\nabla_v R(\mathbf{x}_t, \mathbf{y}_t, \mathbf{v}_t)\|^2}{n(\bar{z}_{t+1}+\bar{z}_{t})} \notag \\
&\leq \bar{z}_{t} + \frac{\|\nabla_y L(\mathbf{x}_t, \mathbf{y}_t)\|^2}{n(\bar{m}^y_{t+1}+\bar{m}^y_{t})} + \frac{\|\nabla_v R(\mathbf{x}_t, \mathbf{y}_t, \mathbf{v}_t)\|^2}{n\bar{z}_{t+1}}\notag \\
&\leq \bar{z}_{t} + \frac{\|\nabla_y L(\mathbf{x}_t, \mathbf{y}_t)\|^2}{n\bar{m}^y_{t+1}} + \frac{\|\nabla_v R(\mathbf{x}_t, \mathbf{y}_t, \mathbf{v}_t)\|^2}{n\bar{z}_{t+1}}.\label{eq88}
\end{align}

Note that, to simplify the proof, we define $\sum_{t=m}^n p_t = 0$ for any $m > n$ and non-negative sequence $\{p_t\}$.
According to the definitions of $k_2$ and $k_3$ in \cref{Lemma6}, the proof can be split into the following four cases.

\textbf{Case 1: Neither $k_2$ nor $k_3$ exists.}  
For any $t \in (0, T)$, we can easily have $\bar{z}_t= \max\{\bar{m}^y_{t}, \bar{m}^v_{t}\} \leq \max\{C_{m^y}, C_{m^v}\} \leq C_z$.

\textbf{Case 2: $k_2$ exists but $k_3$ does not.}  
By using the fourth line of \cref{eq82}, for any $t \in (0, T)$, we have:
\begin{align}
\bar{z}_{t+1}  \leq \bar{m}^y_{t+1}+\bar{m}^v_{t+1} \leq C_{m^y} + \sum_{k=k_2}^t  \frac{\|\nabla_y L(\mathbf{x}_k, \mathbf{y}_k)\|^2}{n\bar{m}^y_{k+1}}  + C_{m^v},\label{eq89}
\end{align}
where we take $\sum_{k=k_2}^t \frac{\|\nabla_y L(\mathbf{x}_k, \mathbf{y}_k)\|^2}{\bar{m}^y_{k+1}} = 0$ for any $t < k_2$.

\textbf{Case 3: $k_3$ exists but $k_2$ does not.}  
From the second line of \cref{eq88}, for any $t \in (0, T)$, we have:
\begin{align}
\bar{z}_{t+1} 
&\leq \bar{z}_{t} + \frac{\|\nabla_y L(\mathbf{x}_t, \mathbf{y}_t)\|^2}{n(\bar{m}^y_{t+1}+\bar{m}^y_{t})} + \frac{\|\nabla_v R(\mathbf{x}_t, \mathbf{y}_t, \mathbf{v}_t)\|^2}{n\bar{z}_{t+1}} \notag \\
&\leq \bar{z}_{k_3} + \sum_{k=k_3}^t  \frac{\|\nabla_y L(\mathbf{x}_k, \mathbf{y}_k)\|^2}{n(\bar{m}^y_{k+1}+\bar{m}^y_{k})} + \sum_{k=k_3}^t \frac{\|\nabla_v R(\mathbf{x}_k, \mathbf{y}_k, \mathbf{v}_k)\|^2}{n\bar{z}_{k+1}}  \notag \\
&\leq \bar{m}^y_{k_3} + \bar{m}^v_{k_3} + \sum_{k=k_3}^t  \frac{\|\nabla_y L(\mathbf{x}_k, \mathbf{y}_k)\|^2}{n(\bar{m}^y_{k+1}+\bar{m}^y_{k})} + \sum_{k=k_3}^t \frac{\|\nabla_v R(\mathbf{x}_k, \mathbf{y}_k, \mathbf{v}_k)\|^2}{n\bar{z}_{k+1}} \notag \\
&\overset{(a)}{=} \bar{m}^y_{t+1} + \bar{m}^v_{k_3} + \sum_{k=k_3}^t \frac{\|\nabla_v R(\mathbf{x}_k, \mathbf{y}_k, \mathbf{v}_k)\|^2}{n\bar{z}_{k+1}} \notag \\
&\leq C_{m^y} + C_{m^v} + \sum_{k=k_3}^t \frac{\|\nabla_v R(\mathbf{x}_k, \mathbf{y}_k, \mathbf{v}_k)\|^2}{n\bar{z}_{k+1}},\label{eq90}
 \end{align}
where we take $\sum_{k=k_3}^t \frac{\|\nabla_v  R(\mathbf{x}_k, \mathbf{y}_k, \mathbf{v}_k)\|^2}{\bar{z}_{k+1}} = 0$ for any $t < k_3$; (a) uses the first line of \cref{eq82}.

\textbf{Case 4: Both $k_2$ and $k_3$ exist.}  
From the third line of \cref{eq90}, for any $t \in (0, T)$, we have:
\begin{align}
\bar{z}_{t+1} 
&\leq \bar{m}^y_{k_3} + \bar{m}^v_{k_3} + \sum_{k=k_3}^t  \frac{\|\nabla_y L(\mathbf{x}_k, \mathbf{y}_k)\|^2}{n\bar{m}^y_{k+1}} + \sum_{k=k_3}^t \frac{\|\nabla_v R(\mathbf{x}_k, \mathbf{y}_k, \mathbf{v}_k)\|^2}{n\bar{z}_{k+1}} \notag \\
&\overset{(a)}{\leq} \bar{m}^y_{k_2}  + \sum_{k=k_2}^{k_3-1} \frac{\|\nabla_y L(\mathbf{x}_k, \mathbf{y}_k)\|^2}{n\bar{m}^y_{k+1}}\nonumber\\
&\quad+ C_{m^v} + \sum_{k=k_3}^t \frac{\|\nabla_y L(\mathbf{x}_k, \mathbf{y}_k)\|^2}{n\bar{m}^y_{k+1}} + \sum_{k=k_3}^t\frac{\|\nabla_v R(\mathbf{x}_k, \mathbf{y}_k, \mathbf{v}_k)\|^2}{n\bar{z}_{k+1}} \notag \\
&= C_{m^y} + C_{m^v} + \sum_{k=k_2}^t \frac{\|\nabla_y L(\mathbf{x}_k, \mathbf{y}_k)\|^2}{n\bar{m}^y_{k+1}} + \sum_{k=k_3}^t \frac{\|\nabla_v R(\mathbf{x}_k, \mathbf{y}_k, \mathbf{v}_k)\|^2}{n\bar{z}_{k+1}},\label{eq91}
\end{align}
where (a) uses the fourth line of \cref{eq82}; we take $\sum_{k=k_2}^{k_3-1} \frac{\|\nabla_y L(\mathbf{x}_k, \mathbf{y}_k)\|^2}{\bar{m}^y_{k+1}} = 0$ when $k_2 \geq k_3$, $\sum_{k=k_2}^t \frac{\|\nabla_y L(\mathbf{x}_k, \mathbf{y}_k)\|^2}{\bar{m}^y_{k+1}} = 0$ for any $t < k_2$, and $\sum_{k=k_3}^t \frac{\|\nabla_v R(\mathbf{x}_k, \mathbf{y}_k, \mathbf{v}_k)\|^2}{\bar{z}_{k+1}} = 0$ for any $t < k_3$. 
It is easy to see that the upper bound of $\bar{z}_{t+1}$ in \cref{eq91} is the largest among all cases. Thus, in the remaining proof, we only explore the upper bound of $\bar{z}_t$ in Case 4.

To further explore the bound of $\bar{z}_t$, we need to use some auxiliary results and bounds. So we split them into three parts as follows:

\textbf{Part I: An Auxiliary Bound of $\sum \frac{\|\bar{\nabla} F(\mathbf{x}_t,\mathbf{y}_t,\mathbf{v}_t)\|^2}{[\bar{m}^x_{t+1}]^2}$.}  
To further explore Case 4, we begin with a common term $\sum_{k=k_0}^t \frac{\|\bar{\nabla} F(\mathbf{x}_k,\mathbf{y}_k,\mathbf{v}_k)\|^2}{[\bar{m}^x_{k+1}]^2}$ for any $k_0 \leq t$. By the strong convexity of $l$ in \cref{Assumption1}, we have:
\begin{align}
\sum_{k=1}^t \frac{\mu^2}{n} \|\mathbf{v}_k\|^2 
&\leq \sum_{k=1}^t \frac{\|\nabla_y \nabla_y L(\mathbf{x}_k, \mathbf{y}_k) \mathbf{v}_k\|^2}{n} \notag \\
&\leq \sum_{k=1}^t \frac{2 \|\nabla_y \nabla_y L(\mathbf{x}_k, \mathbf{y}_k) \mathbf{v}_k - \nabla_y F(\mathbf{x}_k, \mathbf{y}_k)\|^2}{n} 
+ \sum_{k=1}^t \frac{2 \|\nabla_y F(\mathbf{x}_k, \mathbf{y}_k)\|^2}{n} \notag \\
&= \sum_{k=1}^t \frac{2 \|\nabla_v R(\mathbf{x}_k, \mathbf{y}_k, \mathbf{v}_k)\|^2}{n} + \sum_{k=1}^t \frac{2 \|\nabla_y F(\mathbf{x}_k, \mathbf{y}_k)\|^2}{n} \notag \\
&\leq 2 [\bar{m}^v_{t+1}]^2 + 2t C_{f_y}^2,\label{eq92}
\end{align}
which indicates that for any $t \geq 0$, $\|\mathbf{v}_t\|$ can be bounded as:
\begin{align}
\|\mathbf{v}_t\| \leq \frac{\sqrt{2n [\bar{m}^v_{t+1}]^2 + 2nt C_{f_y}^2}}{\mu}\leq \frac{\sqrt{2n [\bar{z}_{t+1}]^2 + 2nt C_{f_y}^2}}{\mu} \leq \frac{\sqrt{2n}\left( \bar{z}_{t+1} + \sqrt{t} C_{f_y} \right)}{\mu}.\label{eq93}
\end{align}
Then we have:
\begin{equation}
    \|\mathbf{v}_t\| \leq \frac{\sqrt{2n}}{\mu} \bar{z}_{t+1} + \frac{\sqrt{2n}C_{f_y}}{\mu} \sqrt{t} =: \bar{a} \bar{z}_{t+1} + \bar{b} \sqrt{t},\label{eq94}
\end{equation}
where $\bar{a}$ and $\bar{b}$ refer to \cref{eq85}. According to \cref{Lemma1}, since $\bar{m}^x_0 \geq 1$, for any integer $t > 0$, we have:
\begin{align}
&\sum_{k=k_0}^t \frac{\| \bar{\nabla} F(\mathbf{x}_{k},\mathbf{y}_{k},\mathbf{v}_{k})\|^2}{[\bar{m}^x_{k+1}]^2}\notag\\
&\leq \sum_{k=0}^t \frac{\| \bar{\nabla} F(\mathbf{x}_{k},\mathbf{y}_{k},\mathbf{v}_{k})\|^2}{[\bar{m}^x_{k+1}]^2} \notag \\
&\leq \log \left( \sum_{k=0}^t \|\bar{\nabla} F(\mathbf{x}_{k},\mathbf{y}_{k},\mathbf{v}_{k})\|^2 + [\bar{m}^x_0]^2 \right) + 1 \notag \\
&\leq \log \left( \sum_{k=0}^t \left(nC_{l_{xy}} \bar{a} \bar{z}_{k+1} + nC_{l_{xy}} \bar{b} \sqrt{k} + nC_{f_x} \right)^2 + [\bar{m}^x_0]^2 \right) + 1 \notag \\
&\leq \log \left( \left(\sum_{k=0}^t nC_{l_{xy}} \bar{a} \bar{z}_{k+1} +n C_{l_{xy}} \bar{b} \sqrt{k} +nC_{f_x} + \bar{m}^x_0 \right)^2\right) + 1 \notag \\
&=2\log \left( \sum_{k=0}^t nC_{l_{xy}} \bar{a} \bar{z}_{k+1} + nC_{l_{xy}} \bar{b} \sqrt{k} + nC_{f_x} + \bar{m}^x_0 \right) + 1 \notag \\
&\leq 2 \log \left((t+1)\left( nC_{l_{xy}} \bar{a} \bar{z}_{t+1} + nC_{l_{xy}} \bar{b} \sqrt{t} + nC_{f_x} + \bar{m}^x_0 \right)\right) + 1 \notag \\
&\leq 2 \log(t + 1) + 2 \log \left(\left( nC_{l_{xy}} \bar{a} \bar{z}_{t+1} + nC_{l_{xy}} \bar{b} + nC_{f_x} + \bar{m}^x_0 \right)\sqrt{t}\right) + 1 \notag \\
&\leq 3 \log(t + 1) + 2 \log \left( nC_{l_{xy}} \bar{a} \bar{z}_{t+1} + nC_{l_{xy}} \bar{b} + nC_{f_x} +\bar{m}^x_0 \right) + 1,\label{eq95}
\end{align}
here we obtain the upper bound of $\sum_{k=k_0}^t \frac{\| \bar{\nabla} F(\mathbf{x}_{k},\mathbf{y}_{k},\mathbf{v}_{k})\|^2}{[\bar{m}^x_{k+1}]^2}$ for any $k_0 \leq t$ in \cref{eq95}. Part I is completed.

\textbf{Part II: A More General Bound of} $\sum\frac{\|\nabla_y L(\mathbf{x}_t, \mathbf{y}_t)\|^2}{\bar{m}^y_{t+1}}$.

In \cref{Lemma7}, we show the bound of $\sum_{k=k_2}^t \frac{\|\nabla_y L(\mathbf{x}_k, \mathbf{y}_k)\|^2}{\bar{m}^y_{k+1}}$
when $k_2$ exists. In Part II, we further provide a rough bound of $\sum_{k=\tilde{k}}^t \frac{\|\nabla_y L(\mathbf{x}_k, \mathbf{y}_k)\|^2}{\bar{m}^y_{k+1}}$
for any potential $\tilde{k} \leq T$. Firstly, if $\tilde{k} \geq k_2$, it is easy to have:
\begin{align}
\sum_{k=\tilde{k}}^t \frac{\|\nabla_y L(\mathbf{x}_k, \mathbf{y}_k)\|^2}{\bar{m}^y_{k+1}}
\leq \sum_{k=k_2}^t \frac{\|\nabla_y L(\mathbf{x}_k, \mathbf{y}_k)\|^2}{\bar{m}^y_{k+1}}.\label{eq96}
\end{align}

Secondly, if $\tilde{k} < k_2$, we have:
\begin{align}
\sum_{k=\tilde{k}}^t \frac{\|\nabla_y L(\mathbf{x}_k, \mathbf{y}_k)\|^2}{\bar{m}^y_{k+1}}
&\leq \sum_{k=\tilde{k}}^{k_2-1}\frac{\|\nabla_y L(\mathbf{x}_k, \mathbf{y}_k)\|^2}{\bar{m}^y_{k+1}}
+ \sum_{k=k_2}^t \frac{\|\nabla_y L(\mathbf{x}_k, \mathbf{y}_k)\|^2}{\bar{m}^y_{k+1}}\nonumber \\
&\leq \frac{\sum_{k=\tilde{k}}^{k_2-1}\|\nabla_y L(\mathbf{x}_k, \mathbf{y}_k)\|^2}{\bar{m}^y_{0}}
+ \sum_{k=k_2}^t \frac{\|\nabla_y L(\mathbf{x}_k, \mathbf{y}_k)\|^2}{\bar{m}^y_{k+1}}\nonumber\\
&\leq \frac{n([\bar{m}^y_{k_2}]^2 - [\bar{m}^y_{\tilde{k}}]^2)}{\bar{m}^y_{0}} 
+ \sum_{k=k_2}^t \frac{\|\nabla_y L(\mathbf{x}_k, \mathbf{y}_k)\|^2}{\bar{m}^y_{k+1}}\nonumber \\
&\leq \frac{n(C_{m^y}^2- [\bar{m}^y_0]^2)}{\bar{m}^y_0}+\sum_{k=k_2}^t \frac{\|\nabla_y L(\mathbf{x}_k, \mathbf{y}_k)\|^2}{\bar{m}^y_{k+1}}\nonumber \\
&= \frac{nC_{m^y}^2}{\bar{m}^y_0} - n\bar{m}^y_0
+\sum_{k=k_2}^t \frac{\|\nabla_y L(\mathbf{x}_k, \mathbf{y}_k)\|^2}{\bar{m}^y_{k+1}}.\label{eq97}
\end{align}

Combining these two situations, since $C_{m^y} \geq \bar{m}^y_0$, for any $\tilde{k} \leq t$, we have:
\begin{align}
&\sum_{k=\tilde{k}}^t \frac{\|\nabla_y L(\mathbf{x}_k, \mathbf{y}_k)\|^2}{\bar{m}^y_{k+1}}\nonumber\\
&\leq \frac{nC_{m^y}^2}{\bar{m}^y_0} - n\bar{m}^y_0
+\sum_{k=k_2}^t \frac{\|\nabla_y L(\mathbf{x}_k, \mathbf{y}_k)\|^2}{\bar{m}^y_{k+1}}\nonumber \\
&\leq \frac{nC_{m^y}^2}{\bar{m}^y_0} - n\bar{m}^y_0 + \frac{ 2nC_{m^y}^2(\mu + L_{l,1})}{\mu^2\gamma_y\sqrt{1+\sigma_u^2}}\nonumber\\
&\quad+\left(\frac{8\Delta_0^x}{1-\rho_W}+\frac{32 \gamma_x^2 \rho_WC_{m^x}^2 (1 + \zeta_q^2)}{\bar{q}_0^2(1 - \rho_W)^2} \right)\left(\frac{(\mu+L_{l,1})^3}{\gamma_y\mu^2}+\frac{2L_{l,1}(\mu+L_{l,1})}{\gamma_y\mu}\right)\nonumber\\
