&\leq4\left(\frac{\Phi(\bar{x}_t)-\Phi(\bar{x}_{t+1})}{\gamma_x }\right)+\frac{4\bar{q}_{t+1}^{-1}(2\gamma_x \bar{L}_{f}^2L_\Phi \bar{q}_{t+1}^{-1} \left(1 +\zeta_q^2\right)+\bar{L}_f^2)}{n} \Delta_t+ \frac{4\bar{L}^2 }{\mu^2} \frac{\|\nabla_v r(\bar{x}_t, \bar{y}_t, \bar{v}_t)\|^2}{\bar{q}_{t+1}}\nonumber\\
&\quad + 8 \bar{q}_{t+1}^{-1}  \left\| \frac{\big(\tilde{\mathbf{q}}_{t+1}^{-1}\big)^\top}{n\bar{q}_{t+1}^{-1}} \bar{\nabla} F(\mathbf{x}_t, \mathbf{y}_t, \mathbf{v}_t) \right\|^2 +\left(\! \frac{2\bar{L}^2}{\mu^2} + \frac{4\bar{L}^2}{\mu^4} \!\!\left(\! \frac{L_{l,2} C_{f_y}}{\mu} + L_{f,1} \!\right)^2 \right)\!\! \frac{\|\nabla_y l(\bar{x}_t, \bar{y}_t)\|^2}{\bar{q}_{t+1}}.\label{eq132}
\end{align}
By taking summation, we have:
\begin{align}
&\sum_{k=k_1}^t  \bar{q}_{k+1}^{-1}\|\nabla_x f(\bar{x}_k, \bar{y}_k, \bar{v}_k)\|^2\nonumber\\
&\leq4\left(\frac{\Phi(\bar{x}_{k_1})-\Phi^*}{\gamma_x}\right)+\frac{4\bar{q}_{0}^{-1}(2\gamma_x \bar{L}_{f}^2L_\Phi \bar{q}_0^{-1} \left(1 +\zeta_q^2\right)+\bar{L}_f^2)}{n}\sum_{k=k_1}^t \Delta_k\nonumber\\
&\quad + \frac{4\bar{L}^2 }{\mu^2\bar{m}^x_{0}}\sum_{k=k_1}^t \frac{\|\nabla_v r(\bar{x}_k, \bar{y}_k, \bar{v}_k)\|^2}{\max\{\bar{m}^y_{k+1},\bar{m}^v_{k+1}\}}+ \frac{8}{\bar{q}_{0}}\sum_{k=k_1}^t \left\| \frac{\big(\tilde{\mathbf{q}}_{k+1}^{-1}\big)^\top}{n\bar{q}_{k+1}^{-1}} \bar{\nabla} F(\mathbf{x}_k, \mathbf{y}_k, \mathbf{v}_k) \right\|^2 \nonumber\\
&\quad+ \left( \frac{2\bar{L}^2}{\mu^2\bar{m}^x_{0}} + \frac{4\bar{L}^2}{\mu^4\bar{m}^x_{0}} \left( \frac{L_{l,2} C_{f_y}}{\mu} + L_{f,1} \right)^2 \right)\sum_{k=k_1}^t \frac{\|\nabla_y l(\bar{x}_k, \bar{y}_k)\|^2}{\max\{\bar{m}^y_{k+1},\bar{m}^v_{k+1}\}}.\label{eq133}
\end{align}
For $\Phi(\bar{x}_{k_1})$, by telescoping \cref{eq129}, we get:
\begin{align}
&\Phi(\bar{x}_{k_1})\leq\Phi(\bar{x}_0)+\frac{\gamma_x\bar{q}_{0}^{-1}(2\gamma_x \bar{L}_{f}^2L_\Phi \bar{q}_{0}^{-1} \left(1 +\zeta_q^2\right)+\bar{L}_f^2)}{n} \sum_{k=0}^{k_1-1}\Delta_k\nonumber\\
&\quad + \frac{\bar{L}^2\gamma_x }{\mu^2} \sum_{k=0}^{k_1-1} \frac{\|\nabla_v r(\bar{x}_k, \bar{y}_k, \bar{v}_k)\|^2}{\bar{m}^x_{k+1}\max\{\bar{m}^y_{k+1},\bar{m}^v_{k+1}\}}+ \frac{2\gamma_x}{\bar{q}_{0}}\sum_{k=0}^{k_1-1} \left\| \frac{\big(\tilde{\mathbf{q}}_{k+1}^{-1}\big)^\top}{n\bar{q}_{k+1}^{-1}} \bar{\nabla} F(\mathbf{x}_k, \mathbf{y}_k, \mathbf{v}_k) \right\|^2 
\nonumber\\
&\quad+{2n\gamma_x^2 L_\Phi \left(1 +\zeta_q^2\right)}\sum_{k=0}^{k_1-1}\frac{\|\nabla_x f(\bar{x}_k, \bar{y}_k, \bar{v}_k)\|^2}{[\bar{m}^x_{k+1}]^2\max\{[\bar{m}^y_{k+1}]^2,[\bar{m}^v_{k+1}]^2\}}\nonumber \\
&\quad + \left( \frac{\gamma_x\bar{L}^2}{2\mu^2} + \frac{\gamma_x\bar{L}^2}{\mu^4} \left( \frac{L_{l,2} C_{f_y}}{\mu} + L_{f,1} \right)^2 \right) \sum_{k=0}^{k_1-1}\frac{\|\nabla_y l(\bar{x}_k, \bar{y}_k)\|^2}{\bar{m}^x_{k+1}\max\{\bar{m}^y_{k+1},\bar{m}^v_{k+1}\}}.\label{eq134}
