By plugging \cref{eq134} into \cref{eq133}, we have:
\begin{align}
&\sum_{k=k_1}^t  \bar{q}_{t+1}^{-1}\|\nabla_x f(\bar{x}_k, \bar{y}_k, \bar{v}_k)\|^2\nonumber\\
&\leq4\left(\frac{\Phi(\bar{x}_{0})-\Phi^*}{\gamma_x}\right)+\frac{4\bar{q}_{0}^{-1}(2\gamma_x \bar{L}_{f}^2L_\Phi \bar{q}_0^{-1} \left(1 +\zeta_q^2\right)+\bar{L}_f^2)}{n}\sum_{k=0}^t \Delta_k\nonumber\\
&\quad+ \frac{4\bar{L}^2}{\mu^2\bar{m}^x_{0}}\sum_{k=0}^t \frac{\|\nabla_v r(\bar{x}_k, \bar{y}_k, \bar{v}_k)\|^2}{\max\{\bar{m}^y_{k+1},\bar{m}^v_{k+1}\}} + \frac{8}{\bar{q}_{0}}\sum_{k=0}^t \left\| \frac{\big(\tilde{\mathbf{q}}_{k+1}^{-1}\big)^\top}{n\bar{q}_{k+1}^{-1}} \bar{\nabla} F(\mathbf{x}_k, \mathbf{y}_k, \mathbf{v}_k) \right\|^2 \nonumber\\
